+describe("DatePicker calendar-day timezone behavior", () => {
+  const timeZone = "Pacific/Kiritimati";
+  const selectedDate = new Date("2024-01-01T12:00:00Z");
+
+  const getDay = (container: HTMLElement, day: string) =>
+    Array.from(container.querySelectorAll(".react-datepicker__day")).find(
+      (element) =>
+        !element.classList.contains("react-datepicker__day--outside-month") &&
+        element.textContent === day,
+    );
+
+  it("uses the configured timezone for calendar selection and input formatting", () => {
+    const onChange = jest.fn();
+    const { container } = render(
+      <DatePicker
+        selected={selectedDate}
+        onChange={onChange}
+        timeZone={timeZone}
+        dateFormat="yyyy-MM-dd"
+      />,
+    );
+
+    expect(container.querySelector("input")?.value).toBe("2024-01-02");
+    fireEvent.focus(container.querySelector("input")!);
+    expect(
+      getDay(container, "2")?.classList.contains(
+        "react-datepicker__day--selected",
+      ),
+    ).toBe(true);
+
+    fireEvent.click(getDay(container, "3")!);
+
+    expect(formatInTimeZone(onChange.mock.calls[0][0], "yyyy-MM-dd", timeZone)).toBe(
+      "2024-01-03",
+    );
+  });
+
+  it("uses the configured timezone when highlighting multiple selected dates", () => {
+    const selectedDates = [
+      selectedDate,
+      new Date("2024-01-03T12:00:00Z"),
+    ];
+    const { container } = render(
+      <DatePicker
+        inline
+        selectsMultiple
+        selectedDates={selectedDates}
+        openToDate={selectedDate}
+        onChange={() => {}}
+        timeZone={timeZone}
+      />,
+    );
+
+    expect(
+      getDay(container, "2")?.classList.contains(
+        "react-datepicker__day--selected",
+      ),
+    ).toBe(true);
+    expect(
+      getDay(container, "4")?.classList.contains(
+        "react-datepicker__day--selected",
+      ),
+    ).toBe(true);
+    expect(
+      getDay(container, "1")?.classList.contains(
+        "react-datepicker__day--selected",
+      ),
+    ).toBe(false);
+  });
+});
